script:
frappe.ui.form.on('Address', {
    onload: function(frm) {
        // Change the labels of the fields
        frm.set_df_property('address_line1', 'label', 'Street Name');
        frm.set_df_property('address_line2', 'label', 'Building Number');
        frm.set_df_property('address_line2', 'reqd', 1);
        // Set pincode field as mandatory
        frm.set_df_property('pincode', 'reqd', 1);
        frm.set_df_property('county', 'hidden', 1);
        frm.set_df_property('state', 'hidden', 1);
    }
});

frappe.ui.form.on('Sales Invoice', {
    onload: function(frm) {
        // Make the is_return field read-only
        frm.set_df_property('is_return', 'read_only', 1);
    }
});
